import json, subprocess, sys, os
env = dict(os.environ, GBRAIN_HOME="/harness-state")
p = subprocess.Popen(["/harness-state/.gbrain/hook-launcher/gbrain-hook", "/harness-state/.local/bin/gbrain",
                      "serve", "--surface", "starter", "--advertise", "verbs"],
                     stdin=subprocess.PIPE, stdout=subprocess.PIPE, stderr=subprocess.DEVNULL, text=True, env=env)
n = 0
def rpc(method, params=None, notify=False):
    global n
    msg = {"jsonrpc": "2.0", "method": method}
    if params is not None: msg["params"] = params
    if not notify:
        n += 1; msg["id"] = n
    p.stdin.write(json.dumps(msg) + "\n"); p.stdin.flush()
    if notify: return None
    while True:
        line = p.stdout.readline()
        if not line: raise SystemExit("server closed")
        r = json.loads(line)
        if r.get("id") == n: return r
rpc("initialize", {"protocolVersion": "2025-06-18", "capabilities": {}, "clientInfo": {"name": "rt", "version": "1"}})
rpc("notifications/initialized", notify=True)
mode = sys.argv[1]
if mode == "remember":
    r = rpc("tools/call", {"name": "remember", "arguments": {"fact": "gbrain MCP round-trip marker 2026-11-21", "provenance": "install-check"}})
elif mode == "recall":
    r = rpc("tools/call", {"name": "recall", "arguments": {"query": sys.argv[2]}})
elif mode == "forget":
    r = rpc("tools/call", {"name": "forget", "arguments": {"fact_id": sys.argv[2]}})
res = r.get("result", r)
for c in res.get("content", []):
    t = c.get("text", "")
    try:
        d = json.loads(t)
        if "facts" in d:
            print(json.dumps([{k: f.get(k) for k in ("fact_id", "fact", "provenance", "origin")} for f in d["facts"]], indent=1))
        else:
            print(json.dumps({k: d.get(k) for k in ("status", "status_text", "id", "fact_id", "state", "error", "code")}))
    except Exception:
        print(t[:800])
print("isError:", res.get("isError"))
p.stdin.close(); p.terminate()

